WITH gaps AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) + INTERVAL '60' DAY THEN 1 ELSE 0 END AS new_group_flag FROM transactions), sessionized AS (SELECT id, account_id, txn_type, txn_time, merchant, is_flagged, SUM(new_group_flag) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT s.id, s.account_id, s.txn_type, s.txn_time, s.merchant, s.is_flagged, s.island_id, (SELECT AVG(t2.amount) FROM transactions t2 WHERE t2.account_id = s.account_id) AS avg_transaction_amount FROM sessionized s ORDER BY avg_transaction_amount NULLS FIRST;
